motionLabel();motion.addEventListener('click',()=>{paused=!paused;motionLabel()});reduced.addEventListener('change',e=>{paused=e.matches;motionLabel()});
new IntersectionObserver(e=>{visible=e[0].isIntersecting}).observe(canvas);
